#!/usr/bin/env python3
"""Apply script: link Portfolio Analysis burning cost into New Business Rating.

Run from the HealthCross repo root: python3 apply_burning_cost_reference.py
Run this BEFORE or AFTER apply_quick_upload_workflow.py - order does not matter,
they touch different backend files (index.html from the other script already
includes this feature's UI, so no overlap there either).
"""
import base64, hashlib, os, sys

MARKER = "BURNING_COST_REFERENCE_2026_08_04"

FILES = [
    {
        'path': 'app/api/routes_portfolio_analysis.py',
        'sha256': '43d63b3932ab852b9ef94ad533e909df29691ad7f79f1de4fb47393afe7d4501',
        'size': 23131,
        'b64': '',
    },
    {
        'path': 'app/scoring/rules/portfolio_analysis.py',
        'sha256': '4943a16383fa029044ff7e08eb573f92a579b6ee7854f1323ad1a8c57ab91d94',
        'size': 22214,
        'b64': '',
    },
    {
        'path': 'tests/test_api_portfolio_analysis.py',
        'sha256': '2646b95bf31951d643f141b72ae4de79ec616c6c3e0f81ab13dd209c6f821a62',
        'size': 34626,
        'b64': '',
    },
    {
        'path': 'tests/test_portfolio_analysis.py',
        'sha256': '8b479945ffdfbc36571ab5b65720d868d0237cba36cc552650d6c8f5e65a268d',
        'size': 30744,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (combined with the quick-upload script, should show 474 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
